CREATE VIEW file_cache AS SELECT t.provider_id AS provider_id,f_source_file.path AS source_file,t.hash AS hash,t.schema_version AS schema_version,t.last_indexed AS last_indexed,t.node_count AS node_count,t.edge_count AS edge_count,t.file_size AS file_size,t.file_mtime_ns AS file_mtime_ns,t.contract_hash AS contract_hash FROM graph_file_cache t LEFT JOIN source_files f_source_file ON f_source_file.file_pk=t.source_file;

CREATE TRIGGER compact_file_cache_insert INSTEAD OF INSERT ON file_cache BEGIN INSERT OR IGNORE INTO source_files(path) SELECT NEW.source_file WHERE NEW.source_file IS NOT NULL AND NOT EXISTS(SELECT 1 FROM source_files WHERE path=NEW.source_file); INSERT INTO graph_file_cache(provider_id,source_file,hash,schema_version,last_indexed,node_count,edge_count,file_size,file_mtime_ns,contract_hash) VALUES(coalesce(NEW.provider_id,'java-core'),(SELECT file_pk FROM source_files WHERE path=NEW.source_file),NEW.hash,NEW.schema_version,coalesce(NEW.last_indexed,CURRENT_TIMESTAMP),coalesce(NEW.node_count,0),coalesce(NEW.edge_count,0),coalesce(NEW.file_size,-1),coalesce(NEW.file_mtime_ns,-1),coalesce(NEW.contract_hash,'')) ON CONFLICT(provider_id,source_file) DO UPDATE SET hash=excluded.hash,schema_version=excluded.schema_version,last_indexed=excluded.last_indexed,node_count=excluded.node_count,edge_count=excluded.edge_count,file_size=excluded.file_size,file_mtime_ns=excluded.file_mtime_ns,contract_hash=excluded.contract_hash; END;

CREATE TRIGGER compact_file_cache_delete INSTEAD OF DELETE ON file_cache BEGIN DELETE FROM graph_file_cache WHERE provider_id IS OLD.provider_id AND source_file IS (SELECT file_pk FROM source_files WHERE path=OLD.source_file); END;

CREATE TABLE graph_file_dependencies (
    source_provider_id TEXT NOT NULL DEFAULT 'java-core',
    source_file INTEGER NOT NULL,
    depends_on_provider_id TEXT NOT NULL DEFAULT 'java-core',
    depends_on_file INTEGER NOT NULL,
    PRIMARY KEY (source_provider_id, source_file, depends_on_provider_id, depends_on_file)
,FOREIGN KEY(source_file) REFERENCES source_files(file_pk)
,FOREIGN KEY(depends_on_file) REFERENCES source_files(file_pk)
);

CREATE VIEW file_dependencies AS SELECT t.source_provider_id AS source_provider_id,f_source_file.path AS source_file,t.depends_on_provider_id AS depends_on_provider_id,f_depends_on_file.path AS depends_on_file FROM graph_file_dependencies t LEFT JOIN source_files f_source_file ON f_source_file.file_pk=t.source_file LEFT JOIN source_files f_depends_on_file ON f_depends_on_file.file_pk=t.depends_on_file;

CREATE TRIGGER compact_file_dependencies_insert INSTEAD OF INSERT ON file_dependencies BEGIN INSERT OR IGNORE INTO source_files(path) SELECT NEW.source_file WHERE NEW.source_file IS NOT NULL AND NOT EXISTS(SELECT 1 FROM source_files WHERE path=NEW.source_file); INSERT OR IGNORE INTO source_files(path) SELECT NEW.depends_on_file WHERE NEW.depends_on_file IS NOT NULL AND NOT EXISTS(SELECT 1 FROM source_files WHERE path=NEW.depends_on_file); INSERT INTO graph_file_dependencies(source_provider_id,source_file,depends_on_provider_id,depends_on_file) VALUES(coalesce(NEW.source_provider_id,'java-core'),(SELECT file_pk FROM source_files WHERE path=NEW.source_file),coalesce(NEW.depends_on_provider_id,'java-core'),(SELECT file_pk FROM source_files WHERE path=NEW.depends_on_file)); END;

CREATE TRIGGER compact_file_dependencies_delete INSTEAD OF DELETE ON file_dependencies BEGIN DELETE FROM graph_file_dependencies WHERE source_provider_id IS OLD.source_provider_id AND source_file IS (SELECT file_pk FROM source_files WHERE path=OLD.source_file) AND depends_on_provider_id IS OLD.depends_on_provider_id AND depends_on_file IS (SELECT file_pk FROM source_files WHERE path=OLD.depends_on_file); END;

CREATE TABLE graph_symbol_dependencies (
    target_key BLOB NOT NULL CHECK (length(target_key) = 8),
    source_file INTEGER NOT NULL,
    PRIMARY KEY (target_key, source_file)
,FOREIGN KEY(source_file) REFERENCES source_files(file_pk)
) WITHOUT ROWID;

CREATE VIEW symbol_dependencies AS SELECT t.target_key AS target_key,f_source_file.path AS source_file FROM graph_symbol_dependencies t LEFT JOIN source_files f_source_file ON f_source_file.file_pk=t.source_file;

CREATE TRIGGER compact_symbol_dependencies_insert INSTEAD OF INSERT ON symbol_dependencies BEGIN INSERT OR IGNORE INTO source_files(path) SELECT NEW.source_file WHERE NEW.source_file IS NOT NULL AND NOT EXISTS(SELECT 1 FROM source_files WHERE path=NEW.source_file); INSERT INTO graph_symbol_dependencies(target_key,source_file) VALUES(NEW.target_key,(SELECT file_pk FROM source_files WHERE path=NEW.source_file)); END;

CREATE TRIGGER compact_symbol_dependencies_delete INSTEAD OF DELETE ON symbol_dependencies BEGIN DELETE FROM graph_symbol_dependencies WHERE target_key IS OLD.target_key AND source_file IS (SELECT file_pk FROM source_files WHERE path=OLD.source_file); END;

CREATE TABLE graph_index_diagnostics (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    severity TEXT NOT NULL CHECK (severity IN ('info','warning','error')),
    code TEXT NOT NULL,
    phase TEXT NOT NULL,
    source_file INTEGER,
    module TEXT,
    scope TEXT,
    symbol TEXT,
    language TEXT,
    provider_id TEXT,
    provider_reason TEXT,
    reason_code TEXT,
    sample_details TEXT,
    occurrence_count INTEGER NOT NULL,
    sample TEXT,
    world TEXT NOT NULL DEFAULT ''
,FOREIGN KEY(source_file) REFERENCES source_files(file_pk)
);

CREATE VIEW index_diagnostics AS SELECT t.id AS id,t.severity AS severity,t.code AS code,t.phase AS phase,f_source_file.path AS source_file,t.module AS module,t.scope AS scope,t.symbol AS symbol,t.language AS language,t.provider_id AS provider_id,t.provider_reason AS provider_reason,t.reason_code AS reason_code,t.sample_details AS sample_details,t.occurrence_count AS occurrence_count,t.sample AS sample,t.world AS world FROM graph_index_diagnostics t LEFT JOIN source_files f_source_file ON f_source_file.file_pk=t.source_file;

CREATE TRIGGER compact_index_diagnostics_insert INSTEAD OF INSERT ON index_diagnostics BEGIN INSERT OR IGNORE INTO source_files(path) SELECT NEW.source_file WHERE NEW.source_file IS NOT NULL AND NOT EXISTS(SELECT 1 FROM source_files WHERE path=NEW.source_file); INSERT INTO graph_index_diagnostics(id,severity,code,phase,source_file,module,scope,symbol,language,provider_id,provider_reason,reason_code,sample_details,occurrence_count,sample,world) VALUES(NEW.id,NEW.severity,NEW.code,NEW.phase,(SELECT file_pk FROM source_files WHERE path=NEW.source_file),NEW.module,NEW.scope,NEW.symbol,NEW.language,NEW.provider_id,NEW.provider_reason,NEW.reason_code,NEW.sample_details,NEW.occurrence_count,NEW.sample,coalesce(NEW.world,'')); END;

CREATE TRIGGER compact_index_diagnostics_delete INSTEAD OF DELETE ON index_diagnostics BEGIN DELETE FROM graph_index_diagnostics WHERE id IS OLD.id; END;

CREATE TABLE graph_analysis_coverage (
    source_file INTEGER NOT NULL,
    module TEXT NOT NULL,
    scope TEXT NOT NULL,
    language TEXT,
    provider_id TEXT NOT NULL DEFAULT 'java-core',
    capability TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('complete','partial','failed')),
    occurrences INTEGER NOT NULL DEFAULT 0,
    groups_count INTEGER NOT NULL DEFAULT 0,
    codes TEXT NOT NULL,
    code_counts TEXT NOT NULL,
    details_truncated INTEGER NOT NULL DEFAULT 0,
    world TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (provider_id, source_file, module, scope, capability, world)
,FOREIGN KEY(source_file) REFERENCES source_files(file_pk)
);

CREATE VIEW analysis_coverage AS SELECT f_source_file.path AS source_file,t.module AS module,t.scope AS scope,t.language AS language,t.provider_id AS provider_id,t.capability AS capability,t.status AS status,t.occurrences AS occurrences,t.groups_count AS groups_count,t.codes AS codes,t.code_counts AS code_counts,t.details_truncated AS details_truncated,t.world AS world FROM graph_analysis_coverage t LEFT JOIN source_files f_source_file ON f_source_file.file_pk=t.source_file;

CREATE TRIGGER compact_analysis_coverage_insert INSTEAD OF INSERT ON analysis_coverage BEGIN INSERT OR IGNORE INTO source_files(path) SELECT NEW.source_file WHERE NEW.source_file IS NOT NULL AND NOT EXISTS(SELECT 1 FROM source_files WHERE path=NEW.source_file); INSERT INTO graph_analysis_coverage(source_file,module,scope,language,provider_id,capability,status,occurrences,groups_count,codes,code_counts,details_truncated,world) VALUES((SELECT file_pk FROM source_files WHERE path=NEW.source_file),NEW.module,NEW.scope,NEW.language,coalesce(NEW.provider_id,'java-core'),NEW.capability,NEW.status,coalesce(NEW.occurrences,0),coalesce(NEW.groups_count,0),NEW.codes,NEW.code_counts,coalesce(NEW.details_truncated,0),coalesce(NEW.world,'')) ON CONFLICT(source_file,module,scope,provider_id,capability,world) DO UPDATE SET language=excluded.language,status=excluded.status,occurrences=excluded.occurrences,groups_count=excluded.groups_count,codes=excluded.codes,code_counts=excluded.code_counts,details_truncated=excluded.details_truncated; END;

CREATE TRIGGER compact_analysis_coverage_delete INSTEAD OF DELETE ON analysis_coverage BEGIN DELETE FROM graph_analysis_coverage WHERE source_file IS (SELECT file_pk FROM source_files WHERE path=OLD.source_file) AND module IS OLD.module AND scope IS OLD.scope AND provider_id IS OLD.provider_id AND capability IS OLD.capability AND world IS OLD.world; END;

CREATE INDEX idx_nodes_kind ON graph_nodes(kind);

CREATE INDEX idx_nodes_symbol_identity ON graph_nodes(symbol_id,module,scope,kind);

CREATE INDEX idx_nodes_qualified_name ON graph_nodes(qualified_name);

CREATE INDEX idx_nodes_package ON graph_nodes(package);

CREATE INDEX idx_nodes_source_file ON graph_nodes(source_file,module,scope);

CREATE INDEX idx_nodes_module ON graph_nodes(module);

CREATE INDEX idx_nodes_scope ON graph_nodes(scope);

CREATE INDEX idx_nodes_producer_file ON graph_nodes(producer_id, source_file);

CREATE INDEX idx_nodes_declaration_filters ON graph_nodes(declaration_kind,visibility,synthetic)
    WHERE declaration_kind IS NOT NULL;

CREATE INDEX idx_nodes_declaring_type ON graph_nodes(declaring_type)
    WHERE declaring_type IS NOT NULL;

CREATE INDEX idx_edges_source_file ON graph_edges(source_file);

CREATE INDEX idx_edges_external_pk ON graph_edges(external_pk) WHERE external_pk IS NOT NULL AND is_external=1;

CREATE INDEX idx_edges_target_relation ON graph_edges(target_id, relation) WHERE target_id IS NOT NULL;

CREATE INDEX idx_edges_relation_external_target ON graph_edges(relation, is_external, target_id) WHERE target_id IS NOT NULL;

CREATE INDEX idx_edges_relation_external_fqn ON graph_edges(relation, is_external, external_pk) WHERE external_pk IS NOT NULL AND is_external=1;

CREATE INDEX idx_edges_external_resolution ON graph_edges(is_external, resolution);

CREATE INDEX idx_edges_source_relation_external ON graph_edges(source_id, relation, is_external);

CREATE INDEX idx_edges_producer_file ON graph_edges(producer_id, source_file);

CREATE INDEX idx_call_site_owners_source ON graph_call_site_owners(source_file, caller_id);

CREATE INDEX idx_call_sites_caller_order ON graph_call_sites(
    owner_pk,begin_line,begin_column,ordinal
);

CREATE INDEX idx_call_site_targets_internal ON graph_call_site_targets(target_id)
    WHERE target_id IS NOT NULL;

CREATE INDEX idx_call_site_targets_external ON graph_call_site_targets(external_pk)
    WHERE external_pk IS NOT NULL;

CREATE INDEX idx_call_site_targets_site ON graph_call_site_targets(call_site_pk);

CREATE INDEX idx_annotations_node_id ON graph_annotations(node_id);

CREATE INDEX idx_annotations_fqn ON graph_annotations(annotation_fqn);

CREATE INDEX idx_annotations_producer_file ON graph_annotations(producer_id, source_file);

CREATE INDEX idx_file_cache_schema_version ON graph_file_cache(schema_version);

CREATE INDEX idx_diagnostics_severity ON graph_index_diagnostics(severity);

CREATE INDEX idx_diagnostics_code ON graph_index_diagnostics(code);

CREATE INDEX idx_diagnostics_source_file ON graph_index_diagnostics(source_file);

CREATE INDEX idx_analysis_coverage_capability
    ON graph_analysis_coverage(capability, module, scope);

CREATE INDEX idx_analysis_coverage_source_file
    ON graph_analysis_coverage(source_file);

CREATE INDEX idx_file_deps_target ON graph_file_dependencies(depends_on_file);

CREATE TABLE project_meta (
    key TEXT PRIMARY KEY,
    value TEXT
);

CREATE TABLE index_providers (
    provider_id TEXT PRIMARY KEY,
    language TEXT NOT NULL,
    provider_version TEXT NOT NULL,
    operations TEXT NOT NULL,
    limitations TEXT NOT NULL,
    profile_hash TEXT NOT NULL
);

CREATE VIRTUAL TABLE node_names USING fts5(qualified_name,label,content='graph_nodes',content_rowid='node_pk');
CREATE TRIGGER nodes_ai AFTER INSERT ON graph_nodes BEGIN INSERT INTO node_names(rowid,qualified_name,label) VALUES(new.node_pk,new.qualified_name,new.label); END;
CREATE TRIGGER nodes_ad AFTER DELETE ON graph_nodes BEGIN INSERT INTO node_names(node_names,rowid,qualified_name,label) VALUES('delete',old.node_pk,old.qualified_name,old.label); END;
CREATE TRIGGER nodes_au AFTER UPDATE OF qualified_name,label ON graph_nodes
WHEN old.qualified_name IS NOT new.qualified_name OR old.label IS NOT new.label BEGIN
 INSERT INTO node_names(node_names,rowid,qualified_name,label) VALUES('delete',old.node_pk,old.qualified_name,old.label);
 INSERT INTO node_names(rowid,qualified_name,label) VALUES(new.node_pk,new.qualified_name,new.label); END;


-- Anatomist schema 33 definitions and lossless file-owned observations.
CREATE TABLE annotation_meta_relations(id INTEGER PRIMARY KEY,
 annotation_fqn TEXT NOT NULL,meta_annotation_fqn TEXT,raw_name TEXT NOT NULL,
 language TEXT NOT NULL,provider_id TEXT NOT NULL DEFAULT 'java-core',
 mechanism TEXT NOT NULL,resolution_status TEXT NOT NULL CHECK(resolution_status IN('exact','heuristic','unresolved')),
 producer_id TEXT NOT NULL DEFAULT 'java-core');
CREATE UNIQUE INDEX idx_annotation_meta_identity ON annotation_meta_relations(
 provider_id,annotation_fqn,coalesce(meta_annotation_fqn,''),raw_name,language,mechanism,producer_id);
CREATE INDEX idx_annotation_meta_source ON annotation_meta_relations(annotation_fqn);
CREATE INDEX idx_annotation_meta_target ON annotation_meta_relations(meta_annotation_fqn);
CREATE TABLE annotation_meta_sources(id INTEGER PRIMARY KEY,
 source_file INTEGER REFERENCES source_files(file_pk),identity_file INTEGER NOT NULL UNIQUE);
CREATE TABLE annotation_meta_owners(relation_id INTEGER NOT NULL REFERENCES annotation_meta_relations(id),
 source_id INTEGER NOT NULL REFERENCES annotation_meta_sources(id),
 resolution_status TEXT NOT NULL CHECK(resolution_status IN('exact','heuristic','unresolved')),
 source_location TEXT,PRIMARY KEY(relation_id,source_id)) WITHOUT ROWID;
CREATE INDEX idx_annotation_meta_owner_source ON annotation_meta_owners(source_id,relation_id);
CREATE VIEW annotation_meta_owned AS SELECT r.id,r.annotation_fqn,r.meta_annotation_fqn,r.raw_name,r.language,
 r.provider_id,r.mechanism,o.resolution_status,f.path AS source_file,o.source_location,r.producer_id
 FROM annotation_meta_owners o JOIN annotation_meta_relations r ON r.id=o.relation_id
 JOIN annotation_meta_sources s ON s.id=o.source_id LEFT JOIN source_files f ON f.file_pk=s.source_file;
CREATE TRIGGER annotation_meta_owned_insert INSTEAD OF INSERT ON annotation_meta_owned BEGIN
 INSERT OR IGNORE INTO source_files(path) SELECT NEW.source_file WHERE NEW.source_file IS NOT NULL;
 INSERT OR IGNORE INTO annotation_meta_sources(source_file,identity_file)
 VALUES((SELECT file_pk FROM source_files WHERE path=NEW.source_file),
 CASE WHEN coalesce(NEW.source_file,'')='' THEN 0 ELSE (SELECT file_pk FROM source_files WHERE path=NEW.source_file) END);
 INSERT OR IGNORE INTO annotation_meta_relations(annotation_fqn,meta_annotation_fqn,raw_name,language,provider_id,mechanism,resolution_status,producer_id)
 VALUES(NEW.annotation_fqn,NEW.meta_annotation_fqn,NEW.raw_name,NEW.language,NEW.provider_id,NEW.mechanism,NEW.resolution_status,NEW.producer_id);
 INSERT OR IGNORE INTO annotation_meta_owners(relation_id,source_id,resolution_status,source_location)
 SELECT r.id,s.id,NEW.resolution_status,NEW.source_location FROM annotation_meta_relations r,annotation_meta_sources s
 WHERE r.provider_id=NEW.provider_id AND r.annotation_fqn=NEW.annotation_fqn
 AND coalesce(r.meta_annotation_fqn,'')=coalesce(NEW.meta_annotation_fqn,'') AND r.raw_name=NEW.raw_name
 AND r.language=NEW.language AND r.mechanism=NEW.mechanism AND r.producer_id=NEW.producer_id
 AND s.identity_file=CASE WHEN coalesce(NEW.source_file,'')='' THEN 0 ELSE (SELECT file_pk FROM source_files WHERE path=NEW.source_file) END;
END;
CREATE TRIGGER annotation_meta_owned_delete INSTEAD OF DELETE ON annotation_meta_owned BEGIN
 DELETE FROM annotation_meta_owners WHERE relation_id=OLD.id AND source_id IN
 (SELECT s.id FROM annotation_meta_sources s LEFT JOIN source_files f ON f.file_pk=s.source_file WHERE f.path IS OLD.source_file);
END;

-- Rust incremental metadata: strings are interned, dependencies have one canonical copy.
CREATE TABLE rust_strings(string_pk INTEGER PRIMARY KEY,value TEXT NOT NULL UNIQUE);
CREATE TABLE graph_rust_source_states(
 source_file INTEGER NOT NULL REFERENCES source_files(file_pk),
 world INTEGER NOT NULL REFERENCES rust_strings(string_pk),state TEXT NOT NULL,
 PRIMARY KEY(source_file,world)) WITHOUT ROWID;
CREATE TABLE graph_rust_analysis_dependencies(
 source_file INTEGER NOT NULL REFERENCES source_files(file_pk),
 world INTEGER NOT NULL REFERENCES rust_strings(string_pk),
 kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 4),
 target_world INTEGER NOT NULL REFERENCES rust_strings(string_pk),
 target_key INTEGER NOT NULL REFERENCES rust_strings(string_pk),
 PRIMARY KEY(source_file,world,kind,target_world,target_key),
 FOREIGN KEY(source_file,world) REFERENCES graph_rust_source_states(source_file,world)) WITHOUT ROWID;
CREATE VIEW rust_source_states AS SELECT f.path AS source_file,w.value AS world,s.state
 FROM graph_rust_source_states s JOIN source_files f ON f.file_pk=s.source_file
 JOIN rust_strings w ON w.string_pk=s.world;
CREATE VIEW rust_analysis_dependencies AS SELECT f.path AS source_file,w.value AS world,
 CASE d.kind WHEN 0 THEN 'file' WHEN 1 THEN 'symbol' WHEN 2 THEN 'lookup' WHEN 3 THEN 'macro' WHEN 4 THEN 'impl_set' END AS kind,
 t.value AS target_world,k.value AS target_key
 FROM graph_rust_analysis_dependencies d JOIN source_files f ON f.file_pk=d.source_file
 JOIN rust_strings w ON w.string_pk=d.world JOIN rust_strings t ON t.string_pk=d.target_world
 JOIN rust_strings k ON k.string_pk=d.target_key;
CREATE TRIGGER compact_rust_state_insert INSTEAD OF INSERT ON rust_source_states BEGIN
 INSERT INTO source_files(path) SELECT NEW.source_file WHERE NOT EXISTS(SELECT 1 FROM source_files WHERE path=NEW.source_file);
 INSERT INTO rust_strings(value) SELECT NEW.world WHERE NOT EXISTS(SELECT 1 FROM rust_strings WHERE value=NEW.world);
 INSERT INTO graph_rust_source_states VALUES(
 (SELECT file_pk FROM source_files WHERE path=NEW.source_file),
 (SELECT string_pk FROM rust_strings WHERE value=NEW.world),json_remove(NEW.state,'$.dependencies'))
 ON CONFLICT(source_file,world) DO UPDATE SET state=excluded.state;
END;
CREATE TRIGGER compact_rust_dependency_insert INSTEAD OF INSERT ON rust_analysis_dependencies BEGIN
 INSERT OR IGNORE INTO rust_strings(value) VALUES(NEW.target_world);
 INSERT OR IGNORE INTO rust_strings(value) VALUES(NEW.target_key);
 INSERT INTO graph_rust_analysis_dependencies VALUES(
 (SELECT file_pk FROM source_files WHERE path=NEW.source_file),
 (SELECT string_pk FROM rust_strings WHERE value=NEW.world),
 CASE NEW.kind WHEN 'file' THEN 0 WHEN 'symbol' THEN 1 WHEN 'lookup' THEN 2 WHEN 'macro' THEN 3 WHEN 'impl_set' THEN 4 END,
 (SELECT string_pk FROM rust_strings WHERE value=NEW.target_world),
 (SELECT string_pk FROM rust_strings WHERE value=NEW.target_key)) ON CONFLICT(source_file,world,kind,target_world,target_key) DO NOTHING;
END;
CREATE TRIGGER compact_rust_dependency_delete INSTEAD OF DELETE ON rust_analysis_dependencies BEGIN
 DELETE FROM graph_rust_analysis_dependencies WHERE
 source_file=(SELECT file_pk FROM source_files WHERE path=OLD.source_file)
 AND world=(SELECT string_pk FROM rust_strings WHERE value=OLD.world)
 AND kind=CASE OLD.kind WHEN 'file' THEN 0 WHEN 'symbol' THEN 1 WHEN 'lookup' THEN 2 WHEN 'macro' THEN 3 WHEN 'impl_set' THEN 4 END
 AND target_world=(SELECT string_pk FROM rust_strings WHERE value=OLD.target_world)
 AND target_key=(SELECT string_pk FROM rust_strings WHERE value=OLD.target_key);
END;
CREATE TRIGGER compact_rust_state_delete INSTEAD OF DELETE ON rust_source_states BEGIN
 DELETE FROM graph_rust_analysis_dependencies WHERE
 source_file=(SELECT file_pk FROM source_files WHERE path=OLD.source_file)
 AND world=(SELECT string_pk FROM rust_strings WHERE value=OLD.world);
 DELETE FROM graph_rust_source_states WHERE
 source_file=(SELECT file_pk FROM source_files WHERE path=OLD.source_file)
 AND world=(SELECT string_pk FROM rust_strings WHERE value=OLD.world);
END;

